import os
D=os.path.dirname(os.path.abspath(__file__));S=open(D+'/../moons_template.r4.html').read()
def rep(s,a,b,n=1):
    assert s.count(a)==n,('rep count',a[:70],s.count(a));return s.replace(a,b)
def cut(s,a,b,new):
    i=s.index(a);assert s.count(a)==1,a[:40];j=s.index(b,i);return s[:i]+new+s[j:]
